import{z as s,x as o,o as n,c as d,q as A,j as r,D as e,d as a,s as i,S as l,b as B}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"教育作为信号","description":"","frontmatter":{"title":"教育作为信号","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/signaling-spence-labor.md","filePath":"econ/signaling-spence-labor.md","lastUpdated":1791413859000}'),p={name:"econ/signaling-spence-labor.md"};function c(C,E,_,h,D,m){const t=o("Mermaid");return n(),d("div",null,[E[2]||(E[2]=A('<h1 id="教育作为信号" tabindex="-1">教育作为信号 <a class="header-anchor" href="#教育作为信号" aria-label="Permalink to &quot;教育作为信号&quot;">​</a></h1><div class="epigraph"><p>若完成教育的成本对高生产率者更低，文凭就能分离类型——哪怕教育本身一无所教。</p><footer>—— 据 Spence, Job Market Signaling, QJE, 1973</footer></div><p><a href="/econ/skill-premium-tinbergen">上一课</a>把溢价写成技能的相对价格，前提仍是教育在生产技能。但教育与工资的正相关有另一条通道：教育不改变生产率，只是标签。信号博弈的技术部分——单交叉、分离与混同、路径外信念——本栏的<a href="/econ/spence-signaling">信号发送</a>已经钉完；本课把那个模型放回劳动市场，算两笔账：信号耗散多少资源、实证怎么把人力资本与信号分开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Becker 口径里教育是投资：付学费买未来的生产率。Spence 口径里教育是筛选装置：类型 \\(\\theta\\in\\{H,L\\}\\) 的生产率 \\(\\theta_H\\gt\\theta_L\\) 与生俱来，教育 \\(e\\) 只改成本 \\(c(e,\\theta)\\)、不改产出；单交叉 \\(c_e(e,L)\\gt c_e(e,H)\\) 让「高类型买高学历」成为均衡，企业按期望产出付工资。缺口不在解均衡，在分账：两个口径里教育的私人回报都为正，社会回报完全不同——若教育零生产率，分离均衡里整个信号支出都是耗散，没有一单位产出为此增加。</p><p><span class="marginnote">术语翻译：「单交叉」就是让两类人的「多读一年书成本曲线」只交叉一次的手段——高类型读得更轻松（边际成本低），于是任何给定的教育量对高类型都更划算。文凭能挑动人，全靠这一条：同一张证书，低类型模仿它太贵。</span></p><h3 id="耗散的规模由阈值区间决定" tabindex="-1">耗散的规模由阈值区间决定 <a class="header-anchor" href="#耗散的规模由阈值区间决定" aria-label="Permalink to &quot;耗散的规模由阈值区间决定&quot;">​</a></h3><p>分离要求低类型不愿模仿、高类型自愿买单：\\(c(e^\\ast,L)\\gt w_H-w_L\\) 且 \\(c(e^\\ast,H)\\lt w_H-w_L\\)。区间内任何 \\(e^\\ast\\) 都是分离均衡，通常聚焦最低成本分离。均衡比较是关键一步：教育补贴降低买信号的成本，分离所需的 \\(e^\\ast\\) 反而上升——人人买更多教育才能分开，产出不变、耗散变大。同一个补贴在 Becker 口径里降低投资成本、抬高真实技能：两个口径对同一政策的福利判断相反。</p><p><span class="marginnote">数字实例：设工资差 \\(w_H-w_L=20\\) 万元。拿到这个学历，高类型只花 15 万元成本，低类型要花 25 万元——那么 15 与 25 之间任何阈值都构成分离均衡，通常选最低那个：高类型买得起、低类型不愿模仿。若补贴把低类型的成本压到 18 万元，原阈值就骗不动低类型了，分离所需的教育量被推着往上走。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>实证分账靠三个可检验的差别。一、羊皮纸效应：若教育是技能增量，工资应随年限平滑上升；若教育是标签，跨过毕业线那年应出现离散跳升。羊皮纸文献确实找到跳升，但同等年限下「多读一年」的平滑部分也在——两种成分并存。二、雇主学习动态：纯信号预测雇佣后雇主逐渐看到真实生产率、教育对工资的预测力随工龄衰减；Altonji–Pierret 2001 发现教育系数随工龄确实下行，但下行慢、不归零——数据落在两口径之间、偏人力资本一侧。三、义务教育断点：被法律多按住一年书的学生后来工资更高，工具变量回报与 OLS 同量级（Card 1999 的口径），这对「只有高能力者才从教育赚钱」的纯信号版故事不利——多读一年对被按住的那类人也增产。</p><p><span class="marginnote">常见误区：初学者容易把羊皮纸效应当成「教育无用论的证据」。实际上毕业年的工资跳升只证明「标签成分存在」，不证明技能增量为零——同一组数据里「多读一年」的平滑增长部分仍指向人力资本。正确读法是两种成分并存，政策评估要分账而不是站队。</span></p>',12)),(n(),r(l,null,{default:e(()=>[i(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E7%B1%BB%E5%9E%8B%20%CE%B8%E2%88%88%7BH%2CL%7D%EF%BC%8C%E7%94%9F%E4%BA%A7%E7%8E%87%E4%B8%8E%E7%94%9F%E4%BF%B1%E6%9D%A5%22%5D%20--%3E%20C%5B%22%E6%95%99%E8%82%B2%E5%8F%AA%E8%BF%9B%E6%88%90%E6%9C%AC%20c(e%2C%CE%B8)%EF%BC%9A%E5%8D%95%E4%BA%A4%E5%8F%89%22%5D%0A%20%20C%20--%3E%20SEP%5B%22%E5%88%86%E7%A6%BB%E5%9D%87%E8%A1%A1%EF%BC%9AH%20%E4%B9%B0%20e*%EF%BC%8CL%20%E4%B8%8D%E6%A8%A1%E4%BB%BF%22%5D%0A%20%20SEP%20--%3E%20WAGE%5B%22%E4%BC%81%E4%B8%9A%E6%8C%89%E7%B1%BB%E5%9E%8B%E4%BB%98%E4%BA%A7%E5%87%BA%EF%BC%9A%E5%B7%A5%E8%B5%84%E5%AE%8C%E5%85%A8%E5%88%86%E9%80%89%22%5D%0A%20%20SEP%20--%3E%20D%5B%22%E8%8B%A5%E6%95%99%E8%82%B2%E9%9B%B6%E7%94%9F%E4%BA%A7%E7%8E%87%EF%BC%9Ae*%20%E5%85%A8%E9%A2%9D%E6%98%AF%E8%80%97%E6%95%A3%22%5D%0A%20%20D%20--%3E%20TEST%5B%22%E5%AE%9E%E8%AF%81%E5%88%86%E8%B4%A6%EF%BC%9A%E7%BE%8A%E7%9A%AE%E7%BA%B8%20%2F%20%E9%9B%87%E4%B8%BB%E5%AD%A6%E4%B9%A0%20%2F%20%E4%B9%89%E5%8A%A1%E6%95%99%E8%82%B2%E6%96%AD%E7%82%B9%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B("h2",{id:"机制",tabindex:"-1"},[a("机制 "),B("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=B("p",null,[a("为什么信号在劳动市场特别强：雇佣前生产率不可见——比柠檬市场更极端，买方连「这辆车」都还没拿到手，只能按类型分布与信号定工资；按事后产出付薪的合同难以执行，事前分选就成了主要机制。信号支出因此是军备竞赛：单个人少买信号会被误判为低类型；均衡里所有人的投入高于最低分离阈值时，超额部分纯是耗散——这与"),B("a",{href:"/econ/spence-signaling"},"信号发送"),a("里精炼常留下最小成本分离的结论相接。")],-1)),(n(),r(l,null,{default:e(()=>[i(t,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20EH%5B%22%E9%AB%98%E7%B1%BB%E5%9E%8B%E9%80%89%20e*%3A%20%E6%88%90%E6%9C%AC%20c(e*%2CH)%20%E4%BD%8E%22%5D%20--%3E%20NET%5B%22%E5%87%80%E5%BE%97%20w_H%20%E2%88%92%20c(e*%2CH)%22%5D%0A%20%20EL%5B%22%E4%BD%8E%E7%B1%BB%E5%9E%8B%E6%9D%83%E8%A1%A1%E6%98%AF%E5%90%A6%E6%A8%A1%E4%BB%BF%22%5D%20--%3E%20CMP%7B%22%E6%A8%A1%E4%BB%BF%E7%9A%84%E8%B4%A6%22%7D%0A%20%20CMP%20--%3E%7C%22c(e*%2CL)%20%E5%A4%A7%E4%BA%8E%20w_H%20%E2%88%92%20w_L%22%7C%20NO%5B%22%E4%B8%8D%E6%A8%A1%E4%BB%BF%3A%20%E7%95%99%E5%9C%A8%20w_L%22%5D%0A%20%20CMP%20--%3E%7C%22c(e*%2CL)%20%E4%B8%8D%E5%A4%A7%E4%BA%8E%20w_H%20%E2%88%92%20w_L%22%7C%20BREAK%5B%22%E5%88%86%E7%A6%BB%E5%A4%B1%E8%B4%A5%3A%20%E6%B7%B7%E5%90%8C%22%5D%0A%20%20NO%20--%3E%20SEP%5B%22%E5%9D%87%E8%A1%A1%E5%88%86%E7%A6%BB%3A%20%E6%96%87%E5%87%AD%E5%8C%BA%E5%88%86%E7%B1%BB%E5%9E%8B%22%5D%0A%20%20NET%20--%3E%20SEP%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=A('<p><span class="marginnote">纯信号世界里教育补贴放大耗散：补贴降低信号成本，分离均衡需要的信号量上升，耗散随补贴增加。真实世界两成分并存，补贴的净效应取决于技能增量与标签成分的占比——评估教育政策最常被跳过的分账。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>两个口径不互斥，占比随教育层次与专业变。别把信号课读成「教育无用」：义务教育断点的正回报、教育对健康的独立效应都在往人力资本一侧加码；也别读成「信号无害」：即便教育真提技能，为分离而过度选购的部分仍是耗散。社会回报与私人回报的差取决于两个参数——信号的耗散份额、技能的生产率增量——现有文献给的是有符号的证据，不是占比的定数。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>教育的私人回报在两个口径下都为正；分账要看社会回报与耗散。</li><li>单交叉下分离均衡存在且多重；聚焦最低成本分离。</li><li>纯信号世界里补贴教育放大耗散；纯人力资本世界里补贴抬高产出，政策判断相反。</li><li>实证分账靠羊皮纸效应、雇主学习动态与义务教育断点；证据两头都有，偏人力资本一侧。</li><li>出处：Spence, QJE 1973；Altonji and Pierret, QJE 2001；Card 1999；Jaeger and Page 1996；Tyler, Murnane and Willett 2000。</li></ul>',5))])}const f=s(p,[["render",c]]);export{u as __pageData,f as default};
